use super::*;
struct OriginalPages{pages:Vec<Vec<u8>>,extent:usize}
struct BorrowedPages<'a>{owner:&'a OriginalPages,authority:Option<(u64,u64)>}
impl RetainedWireByteSource for BorrowedPages<'_>{
 fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{address:self.owner as*const OriginalPages as usize,extent:self.owner.extent,authority:self.authority}}
 fn byte_at(&self,index:usize)->Option<u8>{let mut remaining=index;for page in &self.owner.pages{if remaining<page.len(){return page.get(remaining).copied()}remaining-=page.len()}None}
}
#[test]
fn original_paged_wire_native_preserves_sealed_header_and_actual_funded_field_backing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")};
 let raw:Vec<Vec<u8>>=law["pages"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect()).collect();let encoded=law["json"]["source"].as_str().unwrap().as_bytes();let json:Vec<Vec<u8>>=encoded.chunks(2).map(|bytes|bytes.to_vec()).collect();
 for(is_json,pages)in[(false,raw),(true,json)]{let extent=pages.iter().map(Vec::len).sum();let owner=OriginalPages{pages,extent};let authority=Some((law["identity"]["operation"].as_u64().unwrap(),law["identity"]["generation"].as_u64().unwrap()));for cancelled in[0,1,2,4,32]{let source=BorrowedPages{owner:&owner,authority};let(result,heap)=observe(||if is_json{RetainedWireFieldDecode::new_json_string(&source,(0,extent))}else{RetainedWireFieldDecode::new_range(&source,(0,extent),true)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut decoder=result.unwrap();assert_eq!(decoder.original_source_identity(),source.original_source_identity());let(mut birth,mut release,mut copied)=(0,0,0);
  let changed=BorrowedPages{owner:&owner,authority:Some((9,4))};let(result,heap)=observe(||decoder.advance(&changed,grant));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(decoder.receipt().is_none());
  for _ in 0..cancelled{if decoder.is_ready(){break}let turn=BorrowedPages{owner:&owner,authority};let demand=decoder.demands(&turn,grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}].into_iter().enumerate(){if axis==2&&demand.capacity_bytes==0||axis==3&&demand.copy_bytes==0{continue}let(step,heap)=observe(||decoder.advance(&turn,denied).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(decoder.receipt().is_none())}let(_,heap)=observe(||decoder.advance(&turn,grant).unwrap());let(issued,progress)=decoder.take_receipt().unwrap();assert_eq!(issued,grant);assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));birth+=heap.requested_bytes;release+=heap.released_bytes;copied+=progress.copied_bytes;}
  if cancelled==32{assert!(decoder.is_ready());let mut text=None;let(_,heap)=observe(||decoder.take_text_into(&mut text,grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(decoder.take_receipt().unwrap().1.copied_bytes,0);if is_json{let oracle:String=serde_json::from_str(law["json"]["source"].as_str().unwrap()).unwrap();assert_eq!(text.as_ref().unwrap(),&oracle)}else{let actual=text.as_ref().unwrap().as_bytes().iter().map(|byte|format!("{byte:02x}")).collect::<String>();assert_eq!(actual,law["expectedHex"].as_str().unwrap())}assert_eq!(copied,text.as_ref().unwrap().len());release+=close_received_text(text,grant)}else{decoder.cancel();let demand=decoder.close_demands();if demand.release_bytes>0{let(step,heap)=observe(||decoder.close_step(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0))}let(_,heap)=observe(||decoder.close_step(grant).unwrap());let(issued,progress)=decoder.take_receipt().unwrap();assert_eq!(issued,grant);assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));release+=heap.released_bytes;}
  assert_eq!(birth,release);assert!(decoder.terminal_is_empty());let(_,heap)=observe(||drop(decoder));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(source.original_source_identity().authority,authority);
 }}eprintln!("[DEBUG] Original sealed paged header and operation/generation survive fresh borrowed turn views; fixed2 direct raw/escapedUTF8 writes allocate only actual field backing, partial cancellation and real recipient physical release balance with terminalDrop0");
}
